package com.campusbite.ratings;
import org.springframework.web.server.ResponseStatusException;
import com.campusbite.orders.*;import com.campusbite.users.*;import com.campusbite.menu.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/ratings")
public class FoodRatingController {
 private final FoodRatingRepository ratings;private final OrderRepository orders;private final MenuItemRepository menu;private final UserRepository users;
 public FoodRatingController(FoodRatingRepository r,OrderRepository o,MenuItemRepository m,UserRepository u){ratings=r;orders=o;menu=m;users=u;}
 @PostMapping @PreAuthorize("hasRole('CUSTOMER')") @ResponseStatus(HttpStatus.CREATED) public FoodRating create(@Valid @RequestBody FoodRatingRequest p,Authentication a){CampusOrder o=orders.findById(p.orderId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));if(!o.getCustomerEmail().equalsIgnoreCase(a.getName()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your order");if(o.getStatus()!=OrderStatus.DELIVERED)throw new ResponseStatusException(HttpStatus.CONFLICT,"You can rate after delivery");OrderLine line=o.getItems().stream().filter(x->x.getMenuItemId().equals(p.menuItemId())).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Item is not in this order"));if(ratings.existsByOrderIdAndMenuItemIdAndCustomerEmail(o.getId(),p.menuItemId(),a.getName()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Already rated this item");return ratings.save(new FoodRating(o.getId(),line.getMenuItemId(),line.getName(),a.getName(),o.getOutlet(),p.rating(),p.comment()));}
 @GetMapping("/outlet") @PreAuthorize("hasAnyRole('STAFF','ADMIN','OWNER')") public List<FoodRating> outlet(@RequestParam String outlet,Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow();if(u.getRole()==Role.STAFF&&!outlet.equalsIgnoreCase(u.getAssignedOutlet()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Outside assigned outlet");return ratings.findByOutletOrderByCreatedAtDesc(outlet);}
 @GetMapping("/menu/{id}/average") public Map<String,Object> average(@PathVariable String id){if(!menu.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Menu item not found");List<FoodRating> all=ratings.findByMenuItemId(id);double avg=all.stream().mapToInt(FoodRating::getRating).average().orElse(0);return Map.of("menuItemId",id,"averageRating",Math.round(avg*100.0)/100.0,"ratingCount",all.size());}
}
